{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2186-01-27 19:00:00",
      "speaker": "Doctor",
      "text": "Hello, I'm Dr. Lee. I'll be helping care for you during your stay. You're here for a skin graft on your right foot, correct?"
    },
    {
      "turn_number": 2,
      "time": "2186-01-27 19:02:00",
      "speaker": "Patient",
      "text": "Yes, that’s right. The wound hasn’t healed well since the amputation."
    },
    {
      "turn_number": 3,
      "time": "2186-01-27 19:04:00",
      "speaker": "Doctor",
      "text": "I see. We’ll get you prepped for surgery tomorrow. I also notice you stopped your lasix a few days ago—any reason for that?"
    },
    {
      "turn_number": 4,
      "time": "2186-01-27 19:06:00",
      "speaker": "Patient",
      "text": "I forgot a couple times. I know I shouldn’t, but I don’t feel much different usually."
    },
    {
      "turn_number": 5,
      "time": "2186-01-27 19:08:00",
      "speaker": "Doctor",
      "text": "It’s important to take it regularly. We’re seeing some swelling in your legs, and your heart function isn’t where we want it. We’ll restart it tonight."
    },
    {
      "turn_number": 6,
      "time": "2186-01-27 19:10:00",
      "speaker": "Patient",
      "text": "Okay, but I’ve had a lot of fluid removed before with a lasix drip. Can we just do that now?"
    },
    {
      "turn_number": 7,
      "time": "2186-01-27 19:12:00",
      "speaker": "Doctor",
      "text": "We’ll monitor how you respond to the oral dose first. If needed, we can go to IV or a drip, but we want to avoid over-diuresis."
    },
    {
      "turn_number": 8,
      "time": "2186-01-27 19:14:00",
      "speaker": "Patient",
      "text": "Alright, but I don’t want to get worse before we fix it."
    },
    {
      "turn_number": 9,
      "time": "2186-01-27 19:16:00",
      "speaker": "Doctor",
      "text": "We’ll keep a close eye on you. Your weight and breathing are key signs. Let’s get you settled for the night."
    },
    {
      "turn_number": 10,
      "time": "2186-01-28 14:00:00",
      "speaker": "Doctor",
      "text": "You did well in surgery. The team performed a debridement and applied a skin graft from your thigh to your foot."
    },
    {
      "turn_number": 11,
      "time": "2186-01-28 14:02:00",
      "speaker": "Patient",
      "text": "Good. How’s the graft looking?"
    },
    {
      "turn_number": 12,
      "time": "2186-01-28 14:04:00",
      "speaker": "Doctor",
      "text": "It’s in good position. You’ll need to stay nonweightbearing to protect it. We’ve put you in a special boot for that."
    },
    {
      "turn_number": 13,
      "time": "2186-01-28 14:06:00",
      "speaker": "Patient",
      "text": "Got it. I’ve been coughing a bit—should I be worried?"
    },
    {
      "turn_number": 14,
      "time": "2186-01-28 14:08:00",
      "speaker": "Doctor",
      "text": "We did a chest X-ray. There’s some opacity in your right lung, possibly pneumonia, but your oxygen levels are stable. We don’t think antibiotics are needed yet."
    },
    {
      "turn_number": 15,
      "time": "2186-01-28 14:10:00",
      "speaker": "Patient",
      "text": "But I’ve had this cough for years when I skip my diuretics."
    },
    {
      "turn_number": 16,
      "time": "2186-01-28 14:12:00",
      "speaker": "Doctor",
      "text": "Exactly. It’s likely fluid buildup. That’s why we increased your oral lasix to 60 mg. We’ll watch your breathing closely."
    },
    {
      "turn_number": 17,
      "time": "2186-01-29 08:30:00",
      "speaker": "Doctor",
      "text": "Your chest X-ray shows the right middle lobe opacity has worsened. But no pleural effusion or edema. We still don’t think it’s infection."
    },
    {
      "turn_number": 18,
      "time": "2186-01-29 08:32:00",
      "speaker": "Patient",
      "text": "So what’s causing it?"
    },
    {
      "turn_number": 19,
      "time": "2186-01-29 08:34:00",
      "speaker": "Doctor",
      "text": "Possibly atelectasis or mild pneumonia, but given your history, it’s more likely related to heart failure. We’re keeping you on the higher lasix dose."
    },
    {
      "turn_number": 20,
      "time": "2186-01-29 08:36:00",
      "speaker": "Patient",
      "text": "Can we switch to the IV drip? I really don’t want to struggle to breathe."
    },
    {
      "turn_number": 21,
      "time": "2186-01-29 08:38:00",
      "speaker": "Doctor",
      "text": "We’re transferring you to the heart failure team. They’ll decide on IV diuresis. Your weight is up about 10 pounds, so we know you’re fluid overloaded."
    },
    {
      "turn_number": 22,
      "time": "2186-01-30 10:00:00",
      "speaker": "Doctor",
      "text": "I’m Dr. Patel from the heart failure team. We’re starting you on a lasix drip to help remove excess fluid."
    },
    {
      "turn_number": 23,
      "time": "2186-01-30 10:02:00",
      "speaker": "Patient",
      "text": "Finally. How much fluid do you think I’m holding?"
    },
    {
      "turn_number": 24,
      "time": "2186-01-30 10:04:00",
      "speaker": "Doctor",
      "text": "Your current weight is 144 kg. With diuresis, we aim for a net loss of about 1-2 liters per day. We’ll monitor your kidney function and potassium."
    },
    {
      "turn_number": 25,
      "time": "2186-01-30 10:06:00",
      "speaker": "Patient",
      "text": "I’ve had 70 pounds removed before with a drip. Can we go faster?"
    },
    {
      "turn_number": 26,
      "time": "2186-01-30 10:08:00",
      "speaker": "Doctor",
      "text": "We’ll go steady. Too fast can hurt your kidneys. We’re also continuing your warfarin, ramipril, and spironolactone."
    },
    {
      "turn_number": 27,
      "time": "2186-01-31 09:00:00",
      "speaker": "Doctor",
      "text": "Your telemetry shows frequent PVCs and some NSVT. It’s common with electrolyte shifts during diuresis. We’re replacing potassium."
    },
    {
      "turn_number": 28,
      "time": "2186-01-31 09:02:00",
      "speaker": "Patient",
      "text": "Is that dangerous?"
    },
    {
      "turn_number": 29,
      "time": "2186-01-31 09:04:00",
      "speaker": "Doctor",
      "text": "We’re watching it closely. It’s not sustained, so no immediate treatment needed. Staying hydrated and balanced helps."
    },
    {
      "turn_number": 30,
      "time": "2186-02-01 08:00:00",
      "speaker": "Patient",
      "text": "My eyes are really irritated. I’ve had this for years—dry, crusty, itchy."
    },
    {
      "turn_number": 31,
      "time": "2186-02-01 08:02:00",
      "speaker": "Doctor",
      "text": "We’ve called ophthalmology. It sounds like blepharitis—chronic inflammation from clogged oil glands."
    },
    {
      "turn_number": 32,
      "time": "2186-02-01 08:04:00",
      "speaker": "Patient",
      "text": "Can I get steroid drops? They helped before."
    },
    {
      "turn_number": 33,
      "time": "2186-02-01 08:06:00",
      "speaker": "Doctor",
      "text": "Steroids can worsen eye infections. Ophthalmology recommends warm compresses, baby shampoo lid scrubs, artificial tears, and Restasis."
    },
    {
      "turn_number": 34,
      "time": "2186-02-01 08:08:00",
      "speaker": "Patient",
      "text": "I’ve been using the betadine wipes from my foot for my eyes. Is that okay?"
    },
    {
      "turn_number": 35,
      "time": "2186-02-01 08:10:00",
      "speaker": "Doctor",
      "text": "No, that’s too harsh and can irritate your eyes. Please use only the eye-specific products we provide."
    },
    {
      "turn_number": 36,
      "time": "2186-02-02 10:00:00",
      "speaker": "Doctor",
      "text": "Your echo shows your ejection fraction is now 35%, down from before. There’s also moderate mitral regurgitation and pulmonary hypertension."
    },
    {
      "turn_number": 37,
      "time": "2186-02-02 10:02:00",
      "speaker": "Patient",
      "text": "Is that bad?"
    },
    {
      "turn_number": 38,
      "time": "2186-02-02 10:04:00",
      "speaker": "Doctor",
      "text": "It means your heart isn’t pumping as well. You may benefit from an ICD later. For now, we’re optimizing meds—beta-blocker dose will increase."
    },
    {
      "turn_number": 39,
      "time": "2186-02-03 09:00:00",
      "speaker": "Patient",
      "text": "I feel like I’m peeing nonstop. Is that normal?"
    },
    {
      "turn_number": 40,
      "time": "2186-02-03 09:02:00",
      "speaker": "Doctor",
      "text": "Yes, that’s the lasix working. You’ve lost about 5 liters so far. Your leg swelling is improving."
    },
    {
      "turn_number": 41,
      "time": "2186-02-04 11:00:00",
      "speaker": "Doctor",
      "text": "Your INR is 2.9—good range for warfarin. We’ll keep you on 4 mg daily, down from 5 mg, to stay stable."
    },
    {
      "turn_number": 42,
      "time": "2186-02-04 11:02:00",
      "speaker": "Patient",
      "text": "I’ve had strokes before. Is this dose safe?"
    },
    {
      "turn_number": 43,
      "time": "2186-02-04 11:04:00",
      "speaker": "Doctor",
      "text": "Yes. With your history, your stroke risk is high, so staying in range is crucial. We’ll check it weekly after discharge."
    },
    {
      "turn_number": 44,
      "time": "2186-02-05 08:00:00",
      "speaker": "Patient",
      "text": "My foot feels okay, but I’m worried about healing."
    },
    {
      "turn_number": 45,
      "time": "2186-02-05 08:02:00",
      "speaker": "Doctor",
      "text": "Podiatry checked this morning. The graft looks stable, no signs of infection. Keep it clean, dry, and nonweightbearing."
    },
    {
      "turn_number": 46,
      "time": "2186-02-06 09:00:00",
      "speaker": "Doctor",
      "text": "Your breathing is easier, and your weight is down. We’re switching from IV lasix to oral—40 mg twice daily."
    },
    {
      "turn_number": 47,
      "time": "2186-02-06 09:02:00",
      "speaker": "Patient",
      "text": "That’s great. Can I go home soon?"
    },
    {
      "turn_number": 48,
      "time": "2186-02-06 09:04:00",
      "speaker": "Doctor",
      "text": "Soon. We need to make sure your electrolytes and kidney function stay stable on the oral dose."
    },
    {
      "turn_number": 49,
      "time": "2186-02-07 10:00:00",
      "speaker": "Patient",
      "text": "I’ve been using the warm compresses and Restasis. My eyes feel a little better."
    },
    {
      "turn_number": 50,
      "time": "2186-02-07 10:02:00",
      "speaker": "Doctor",
      "text": "Good. Ophthalmology also gave you ivermectin for possible mite involvement. Keep up the routine."
    },
    {
      "turn_number": 51,
      "time": "2186-02-08 08:00:00",
      "speaker": "Doctor",
      "text": "Your latest labs show creatinine at 1.4 and potassium normal. We’ll keep the same diuretic plan."
    },
    {
      "turn_number": 52,
      "time": "2186-02-09 09:00:00",
      "speaker": "Patient",
      "text": "I’ve been weighing myself. Down 8 pounds since admission."
    },
    {
      "turn_number": 53,
      "time": "2186-02-09 09:02:00",
      "speaker": "Doctor",
      "text": "Excellent. That’s a good sign you’re losing fluid. Keep doing that every morning."
    },
    {
      "turn_number": 54,
      "time": "2186-02-10 10:00:00",
      "speaker": "Doctor",
      "text": "We’re stopping the IV. You’re doing well on oral meds. Your graft is healing, and heart failure symptoms are improved."
    },
    {
      "turn_number": 55,
      "time": "2186-02-10 10:02:00",
      "speaker": "Patient",
      "text": "When can I go home?"
    },
    {
      "turn_number": 56,
      "time": "2186-02-10 10:04:00",
      "speaker": "Doctor",
      "text": "Likely in a few days. We’ll schedule your follow-up appointments first."
    },
    {
      "turn_number": 57,
      "time": "2186-02-15 09:00:00",
      "speaker": "Doctor",
      "text": "You’re ready for discharge. Your swelling is much better, heart function stable, and graft is intact."
    },
    {
      "turn_number": 58,
      "time": "2186-02-15 09:02:00",
      "speaker": "Patient",
      "text": "What meds am I taking now?"
    },
    {
      "turn_number": 59,
      "time": "2186-02-15 09:04:00",
      "speaker": "Doctor",
      "text": "Torsemide 40 mg twice daily, spironolactone, ramipril, warfarin 4 mg, metoprolol 25 mg daily, and your diabetes meds. Plus eye drops and ointment."
    },
    {
      "turn_number": 60,
      "time": "2186-02-15 09:06:00",
      "speaker": "Patient",
      "text": "And I need to keep the dressing on until my podiatry visit?"
    },
    {
      "turn_number": 61,
      "time": "2186-02-15 09:08:00",
      "speaker": "Doctor",
      "text": "Exactly. Keep it dry, don’t bear weight, and call if you see redness, drainage, or increased pain."
    },
    {
      "turn_number": 62,
      "time": "2186-02-15 09:10:00",
      "speaker": "Patient",
      "text": "And weigh myself every day?"
    },
    {
      "turn_number": 63,
      "time": "2186-02-15 09:12:00",
      "speaker": "Doctor",
      "text": "Yes. Call if you gain more than 3 pounds in a day or 5 in a week."
    },
    {
      "turn_number": 64,
      "time": "2186-02-15 09:14:00",
      "speaker": "Patient",
      "text": "Got it. Thanks for helping me through this."
    },
    {
      "turn_number": 65,
      "time": "2186-02-15 09:16:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and we’ll see you in follow-up."
    },
    {
      "turn_number": 66,
      "time": "2186-02-18 10:00:00",
      "speaker": "Doctor",
      "text": "Just confirming—you have your prescriptions, follow-up appointments, and lab orders?"
    },
    {
      "turn_number": 67,
      "time": "2186-02-18 10:02:00",
      "speaker": "Patient",
      "text": "Yes, all set. Podiatry in a week, cardiology in two weeks, and labs this Friday."
    },
    {
      "turn_number": 68,
      "time": "2186-02-18 10:04:00",
      "speaker": "Doctor",
      "text": "Perfect. Remember, call if you have fever, chest pain, trouble breathing, or wound issues."
    },
    {
      "turn_number": 69,
      "time": "2186-02-18 10:06:00",
      "speaker": "Patient",
      "text": "I will. I feel a lot better than when I came in."
    },
    {
      "turn_number": 70,
      "time": "2186-02-18 10:08:00",
      "speaker": "Doctor",
      "text": "That’s the goal. You’ve made great progress. Safe travels home."
    },
    {
      "turn_number": 71,
      "time": "2186-02-18 10:10:00",
      "speaker": "Patient",
      "text": "Thank you, doctor."
    },
    {
      "turn_number": 72,
      "time": "2186-02-18 10:12:00",
      "speaker": "Doctor",
      "text": "Take care. We’re here if you need us."
    },
    {
      "turn_number": 73,
      "time": "2186-02-18 10:14:00",
      "speaker": "Patient",
      "text": "I’ll follow all the instructions."
    },
    {
      "turn_number": 74,
      "time": "2186-02-18 10:16:00",
      "speaker": "Doctor",
      "text": "That’s all we ask. Have a good recovery."
    },
    {
      "turn_number": 75,
      "time": "2186-02-18 10:18:00",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    },
    {
      "turn_number": 76,
      "time": "2186-02-18 10:20:00",
      "speaker": "Doctor",
      "text": "You’re welcome. See you soon."
    },
    {
      "turn_number": 77,
      "time": "2186-02-18 10:22:00",
      "speaker": "Patient",
      "text": "Bye."
    },
    {
      "turn_number": 78,
      "time": "2186-02-18 10:24:00",
      "speaker": "Doctor",
      "text": "Take care."
    },
    {
      "turn_number": 79,
      "time": "2186-02-18 10:26:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 80,
      "time": "2186-02-18 10:28:00",
      "speaker": "Doctor",
      "text": "Feel free to call with any concerns."
    },
    {
      "turn_number": 81,
      "time": "2186-02-18 10:30:00",
      "speaker": "Patient",
      "text": "I will. Appreciate it."
    },
    {
      "turn_number": 82,
      "time": "2186-02-18 10:32:00",
      "speaker": "Doctor",
      "text": "You’re doing great. Keep it up."
    },
    {
      "turn_number": 83,
      "time": "2186-02-18 10:34:00",
      "speaker": "Patient",
      "text": "I will. Thanks."
    },
    {
      "turn_number": 84,
      "time": "2186-02-18 10:36:00",
      "speaker": "Doctor",
      "text": "Have a safe trip home."
    },
    {
      "turn_number": 85,
      "time": "2186-02-18 10:38:00",
      "speaker": "Patient",
      "text": "I will. Bye."
    }
  ],
  "summary": {
    "admission_start": "2186-01-27 18:44:00",
    "admission_end": "2186-02-18 16:30:00",
    "summary_paragraph": "A 50-year-old male with a history of type II diabetes, morbid obesity, atrial fibrillation, and prior right hallux amputation was admitted for a planned split-thickness skin graft from the right thigh to foot. Postoperatively, he developed worsening lower extremity edema and dyspnea, leading to transfer to the heart failure service for management of acute on chronic systolic heart failure. He was treated with intravenous and oral diuresis, achieving significant fluid loss and symptom improvement. His ejection fraction was found to be reduced at 35%, with moderate mitral regurgitation and pulmonary hypertension. The skin graft remained stable without infection. He was also managed for chronic blepharitis with ophthalmology input and optimized on heart failure and anticoagulation therapy. He was discharged home with follow-up arranged and instructions for weight monitoring, wound care, and medication adherence.",
    "problems": [
      "Encounter for planned post-operative wound closure",
      "Acute on chronic systolic heart failure",
      "Other primary cardiomyopathies",
      "Atrial fibrillation",
      "Body Mass Index 45.0-49.9, adult",
      "Morbid obesity",
      "Ulcer of other part of foot",
      "Long-term (current) use of anticoagulants",
      "Diabetes mellitus without mention of complication, type II or unspecified type, not stated as uncontrolled",
      "Obstructive sleep apnea (adult)(pediatric)",
      "Long-term (current) use of insulin",
      "Congestive heart failure, unspecified",
      "Blepharitis, unspecified",
      "Mitral valve disorders"
    ]
  }
}
